import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a minimum-cost shared multicast tree using exact subset DP."""
    import heapq

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dsts))
    h = nx.DiGraph()
    h.add_nodes_from(G.nodes)

    for u, v, data in G.edges(data=True):
        cost = data.get("cost")
        if u != v and cost is not None:
            h.add_edge(u, v, cost=float(cost))

    if src not in h or not terminals:
        return topology

    def install(routes):
        for dst in dsts:
            path = routes.get(dst)
            if path is None:
                continue
            edges = [[u, v, G[u][v]] for u, v in zip(path, path[1:])]
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, list(edges))

    # Exact directed Steiner DP is practical for typical broadcast fan-outs.
    # For larger sets, use a shared-edge marginal-cost approximation.
    if len(terminals) > 12:
        selected, routes, remaining = set(), {}, set(terminals)
        while remaining:
            def marginal(u, v, data):
                return 0.0 if (u, v) in selected else data["cost"]

            distances, paths = nx.single_source_dijkstra(h, src, weight=marginal)
            reachable = [d for d in remaining if d in paths]
            if not reachable:
                break
            dst = min(reachable, key=lambda d: (distances[d], str(d)))
            routes[dst] = paths[dst]
            selected.update(zip(paths[dst], paths[dst][1:]))
            remaining.remove(dst)
        install(routes)
        return topology

    nodes = list(h.nodes)
    count = len(terminals)
    limit = 1 << count
    inf = float("inf")
    dp = [{node: inf for node in nodes} for _ in range(limit)]
    splits = [{} for _ in range(limit)]
    hops = [{} for _ in range(limit)]

    # dp[mask][node] is the minimum union-link cost of a tree rooted at node
    # spanning every terminal represented by mask.
    for mask in range(1, limit):
        if mask & (mask - 1) == 0:
            terminal = terminals[mask.bit_length() - 1]
            if terminal in h:
                dp[mask][terminal] = 0.0
        else:
            subset = (mask - 1) & mask
            while subset:
                other = mask ^ subset
                if subset < other:
                    for node in nodes:
                        value = dp[subset][node] + dp[other][node]
                        if value < dp[mask][node]:
                            dp[mask][node] = value
                            splits[mask][node] = (subset, other)
                subset = (subset - 1) & mask

        queue = []
        serial = 0
        for node in nodes:
            if dp[mask][node] < inf:
                heapq.heappush(queue, (dp[mask][node], serial, node))
                serial += 1

        # Reverse Dijkstra evaluates the recurrence:
        # dp[mask][parent] = edge(parent, child) + dp[mask][child].
        while queue:
            distance, _, child = heapq.heappop(queue)
            if distance != dp[mask][child]:
                continue
            for parent in h.predecessors(child):
                value = distance + h[parent][child]["cost"]
                if value < dp[mask][parent]:
                    dp[mask][parent] = value
                    hops[mask][parent] = child
                    heapq.heappush(queue, (value, serial, parent))
                    serial += 1

    full = limit - 1
    if dp[full][src] == inf:
        return topology

    selected, visited = set(), set()

    def collect(mask, node):
        """Recover paid links from the DP split and extension decisions."""
        state = (mask, node)
        if state in visited:
            return
        visited.add(state)
        if node in hops[mask]:
            child = hops[mask][node]
            selected.add((node, child))
            collect(mask, child)
        elif node in splits[mask]:
            left, right = splits[mask][node]
            collect(left, node)
            collect(right, node)

    collect(full, src)
    tree = nx.DiGraph()
    tree.add_edges_from(selected)
    routes = {}

    for dst in terminals:
        try:
            routes[dst] = nx.shortest_path(tree, src, dst)
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass

    install(routes)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


